        bias = _round6(math.fsum(residuals) / matched)
        rmse = _round6(
            math.sqrt(math.fsum(r * r for r in residuals) / matched)
        )
        max_abs = _round6(max(abs(r) for r in residuals))
    else:
        bias = rmse = max_abs = 0.0
