    grade = (
        "pass"
        if missing == 0 and matched > 0 and within == matched
        else "fail"
    )

    return {
        "matched": matched,
        "missing": int(missing),
        "bias": bias,
        "rmse": rmse,
        "max_abs": max_abs,
        "within_tolerance": int(within),
        "quality": grade,
    }

